-- Cascades that drop a view also drop the columns, attributes and domains
-- of its row type.
CREATE FUNCTION f() RETURNS int LANGUAGE sql AS 'SELECT 1';
CREATE VIEW v AS SELECT f() AS a;
CREATE TABLE t (k int, c v);
CREATE TYPE ct AS (x v);
CREATE DOMAIN dv AS v;
DROP FUNCTION f();
DROP FUNCTION f() CASCADE;
SELECT relname FROM pg_class WHERE relname IN ('v','t') ORDER BY 1;
SELECT attname FROM pg_attribute WHERE attrelid = 't'::regclass AND attnum > 0 ORDER BY attnum;
SELECT typname FROM pg_type WHERE typname IN ('ct','dv') ORDER BY 1;
CREATE SEQUENCE sq;
CREATE VIEW v2 AS SELECT last_value FROM sq;
CREATE TABLE t2 (c v2);
DROP SEQUENCE sq CASCADE;
CREATE TYPE e AS ENUM ('a');
CREATE VIEW v3 AS SELECT 'a'::e AS a;
CREATE TABLE t3 (c v3);
DROP TYPE e CASCADE;
CREATE COLLATION co (provider = libc, locale = 'C');
CREATE VIEW v4 AS SELECT 'a' COLLATE co AS a;
CREATE TABLE t4 (c v4);
DROP COLLATION co CASCADE;
CREATE FUNCTION fo(int, int) RETURNS bool LANGUAGE sql AS 'SELECT true';
CREATE OPERATOR === (FUNCTION = fo, LEFTARG = int, RIGHTARG = int);
CREATE VIEW v5 AS SELECT 1 === 2 AS a;
CREATE TABLE t5 (c v5);
DROP OPERATOR === (int, int) CASCADE;
CREATE TEXT SEARCH CONFIGURATION tc (COPY = simple);
CREATE VIEW v6 AS SELECT to_tsvector('tc', 'a') AS a;
CREATE TABLE t6 (c v6);
DROP TEXT SEARCH CONFIGURATION tc CASCADE;
SELECT relname FROM pg_class WHERE relname ~ '^[vt][0-9]?$' ORDER BY 1;
DROP TABLE t, t2, t3, t4, t5, t6;
DROP TYPE ct;
CREATE TABLE b (k int, x int);
CREATE VIEW v AS SELECT x FROM b;
CREATE TABLE t (c v);
CREATE TYPE ct AS (a int, f v);
CREATE DOMAIN dv AS v;
ALTER TABLE b DROP COLUMN x CASCADE;
SELECT relname FROM pg_class WHERE relname IN ('v','t') ORDER BY 1;
SELECT attname FROM pg_attribute WHERE attrelid IN ('t'::regclass, 'ct'::regclass) AND attnum > 0 ORDER BY attrelid, attnum;
SELECT typname FROM pg_type WHERE typname IN ('ct','dv') ORDER BY 1;
CREATE DOMAIN d AS int;
CREATE VIEW v2 AS SELECT 1::d AS a;
CREATE TABLE t2 (c v2[]);
DROP DOMAIN d CASCADE;
CREATE FUNCTION sf(int, int) RETURNS int LANGUAGE sql AS 'SELECT $1 + $2';
CREATE AGGREGATE ag (int) (SFUNC = sf, STYPE = int);
CREATE VIEW v3 AS SELECT ag(k) AS a FROM b;
CREATE TABLE t3 (c v3);
DROP AGGREGATE ag(int) CASCADE;
CREATE ROLE r;
SET ROLE r;
CREATE FUNCTION rf() RETURNS int LANGUAGE sql AS 'SELECT 1';
RESET ROLE;
CREATE VIEW v4 AS SELECT rf() AS a;
CREATE TABLE t4 (c v4);
DROP OWNED BY r CASCADE;
DROP ROLE r;
SELECT relname FROM pg_class WHERE relname ~ '^[vt][0-9]?$' ORDER BY 1;
DROP TABLE b, t, t2, t3, t4;
DROP TYPE ct;
DROP FUNCTION fo(int, int), sf(int, int);
